INSERT INTO DimTrade (TradeID, SK_BrokerID, SK_CreateDateID, SK_CreateTimeID, SK_CloseDateID, SK_CloseTimeID, Status, DT_Type, CashFlag, SK_SecurityID, SK_CompanyID, Quantity, BidPrice, SK_CustomerID, SK_AccountID, ExecutedBy, TradePrice, Fee, Commission, Tax, BatchID) WITH TradeEvents AS (SELECT TH.TH_T_ID AS TradeID, MIN(CASE WHEN TH.TH_ST_ID = 'PNDG' OR (TH.TH_ST_ID = 'SBMT' AND T.T_TT_ID IN ('TMB', 'TMS')) THEN TH.TH_DTS END) AS CreateTS, MAX(CASE WHEN TH.TH_ST_ID IN ('CMPT', 'CNCL') THEN TH.TH_DTS END) AS CloseTS, MIN(TH.TH_DTS) AS FirstSeenTS FROM Source.TradeHistory AS TH INNER JOIN Source.Trade AS T ON T.T_ID = TH.TH_T_ID GROUP BY TH.TH_T_ID), DimTradeStaging AS (SELECT CAST(T.T_ID AS INT) AS TradeID, DA.SK_BrokerID AS SK_BrokerID, E.CreateTS AS CreateTS, E.CloseTS AS CloseTS, CAST(ST.ST_NAME AS TEXT) AS Status, CAST(TT.TT_NAME AS TEXT) AS DT_Type, CASE WHEN T.T_IS_CASH = '1' THEN TRUE ELSE FALSE END AS CashFlag, DS.SK_SecurityID AS SK_SecurityID, DS.SK_CompanyID AS SK_CompanyID, COALESCE(TRY_CAST(T.T_QTY AS DECIMAL(6, 0)), 0) AS Quantity, COALESCE(TRY_CAST(T.T_BID_PRICE AS DECIMAL(8, 2)), 0.00) AS BidPrice, DA.SK_CustomerID AS SK_CustomerID, DA.SK_AccountID AS SK_AccountID, CAST(T.T_EXEC_NAME AS TEXT) AS ExecutedBy, TRY_CAST(T.T_TRADE_PRICE AS DECIMAL(8, 2)) AS TradePrice, TRY_CAST(T.T_CHRG AS DECIMAL(10, 2)) AS Fee, NULL AS Commission, TRY_CAST(T.T_TAX AS DECIMAL(10, 2)) AS Tax, CAST(1 AS DECIMAL(5)) AS BatchID FROM Source.Trade AS T INNER JOIN TradeEvents AS E ON T.T_ID = E.TradeID INNER JOIN Source.StatusType AS ST ON T.T_ST_ID = ST.ST_ID INNER JOIN Source.TradeType AS TT ON T.T_TT_ID = TT.TT_ID LEFT JOIN DimAccount AS DA ON DA.AccountID = T.T_CA_ID AND DA.EffectiveDate <= CAST(E.FirstSeenTS AS DATE) AND CAST(E.FirstSeenTS AS DATE) < DA.EndDate LEFT JOIN DimSecurity AS DS ON DS.Symbol = T.T_S_SYMB AND DS.EffectiveDate <= CAST(E.FirstSeenTS AS DATE) AND CAST(E.FirstSeenTS AS DATE) < DS.EndDate) SELECT CAST(TradeID AS INT) AS TradeID, CAST(SK_BrokerID AS INT) AS SK_BrokerID, CAST((SELECT SK_DateID FROM DimDate WHERE DateValue = CAST(DimTradeStaging.CreateTS AS DATE)) AS INT) AS SK_CreateDateID, CAST((SELECT SK_TimeID FROM DimTime WHERE TimeValue = CAST(DimTradeStaging.CreateTS AS TIME)) AS INT) AS SK_CreateTimeID, CAST((SELECT SK_DateID FROM DimDate WHERE DateValue = CAST(DimTradeStaging.CloseTS AS DATE)) AS INT) AS SK_CloseDateID, CAST((SELECT SK_TimeID FROM DimTime WHERE TimeValue = CAST(DimTradeStaging.CloseTS AS TIME)) AS INT) AS SK_CloseTimeID, CAST(Status AS TEXT) AS Status, CAST(DT_Type AS TEXT) AS DT_Type, CAST(CashFlag AS BOOLEAN) AS CashFlag, CAST(SK_SecurityID AS INT) AS SK_SecurityID, CAST(SK_CompanyID AS INT) AS SK_CompanyID, CAST(Quantity AS DECIMAL(6, 0)) AS Quantity, CAST(BidPrice AS DECIMAL(8, 2)) AS BidPrice, CAST(SK_CustomerID AS INT) AS SK_CustomerID, CAST(SK_AccountID AS INT) AS SK_AccountID, CAST(ExecutedBy AS TEXT) AS ExecutedBy, CAST(TradePrice AS DECIMAL(8, 2)) AS TradePrice, CAST(Fee AS DECIMAL(10, 2)) AS Fee, CAST(Commission AS DECIMAL(10, 2)) AS Commission, CAST(Tax AS DECIMAL(10, 2)) AS Tax, CAST(BatchID AS DECIMAL(5, 0)) AS BatchID FROM DimTradeStaging;
